/**
 * Panel styles for the right Sidebar's narrow column.
 *
 * Every colour comes from a Host `--dsw-alias-*` token. The fallbacks are
 * deliberately neutral — a `color-mix` of `currentColor`, or `transparent` —
 * because a literal light palette would be legible in a light theme and wrong
 * in a dark one, which is exactly the failure a themed selector is here to fix.
 */
/** The stylesheet this plugin installs for the lifetime of its Client run. */
export declare const STYLES = "\n.gt-root {\n  display: flex;\n  flex-direction: column;\n  height: 100%;\n  min-height: 0;\n  background: var(--dsw-alias-bg-base, transparent);\n  color: var(--dsw-alias-label-primary, inherit);\n  font-family: var(--dsw-font-family, inherit);\n  font-size: 13px;\n  line-height: 1.45;\n}\n\n/* \u2500\u2500 header: the JDK picker and the two icon controls \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */\n\n.gt-header {\n  display: flex;\n  flex: none;\n  align-items: center;\n  gap: 6px;\n  padding: 8px 8px 6px;\n}\n\n.gt-java {\n  position: relative;\n  display: inline-flex;\n  flex: 1 1 auto;\n  align-items: center;\n  gap: 6px;\n  min-width: 0;\n  padding: 3px 6px 3px 8px;\n  border: 0.5px solid var(--dsw-alias-border-l4, currentColor);\n  border-radius: var(--dsw-radius-sm, 8px);\n  background: var(--dsw-alias-bg-layer-1, transparent);\n}\n\n.gt-java[data-open='true'] {\n  border-color: var(--dsw-alias-state-business-primary, currentColor);\n}\n\n.gt-java-label {\n  flex: none;\n  color: var(--dsw-alias-label-tertiary, inherit);\n  font-size: 11.5px;\n  letter-spacing: 0.01em;\n}\n\n.gt-picker-trigger {\n  display: flex;\n  flex: 1 1 auto;\n  align-items: center;\n  gap: 4px;\n  min-width: 0;\n  min-height: 20px;\n  padding: 0;\n  border: 0;\n  background: none;\n  color: var(--dsw-alias-label-primary, inherit);\n  font: inherit;\n  font-size: 12.5px;\n  text-align: left;\n  cursor: pointer;\n}\n\n.gt-picker-trigger:disabled {\n  cursor: default;\n}\n\n.gt-picker-trigger:focus-visible {\n  outline: var(--dsw-focus-ring-width, 2px) solid var(--dsw-alias-state-business-primary, currentColor);\n  outline-offset: 2px;\n  border-radius: 4px;\n}\n\n.gt-picker-text {\n  min-width: 0;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.gt-picker-dim {\n  color: var(--dsw-alias-label-tertiary, inherit);\n}\n\n.gt-picker-caret {\n  display: inline-flex;\n  flex: none;\n  align-items: center;\n  color: var(--dsw-alias-label-tertiary, inherit);\n}\n\n/* The popup sits inside the page, above the tree and above a floating pane. */\n.gt-popup {\n  position: absolute;\n  top: calc(100% + 4px);\n  left: 0;\n  z-index: 1050;\n  display: flex;\n  flex-direction: column;\n  box-sizing: border-box;\n  min-width: 240px;\n  max-width: min(420px, calc(100vw - 24px));\n  max-height: 320px;\n  padding: 4px;\n  overflow: auto;\n  border: 0.5px solid var(--dsw-alias-border-l4, currentColor);\n  border-radius: var(--dsw-radius-md, 12px);\n  background: var(--dsw-specific-menu, var(--dsw-alias-bg-layer-2, Canvas));\n  box-shadow: var(--dsw-elevation-panel, 0 6px 20px rgb(0 0 0 / 18%));\n  backdrop-filter: var(--dsw-menu-backdrop-filter, none);\n}\n\n.gt-popup-above {\n  top: auto;\n  bottom: calc(100% + 4px);\n}\n\n.gt-option {\n  display: flex;\n  flex-direction: column;\n  gap: 1px;\n  width: 100%;\n  box-sizing: border-box;\n  padding: 5px 8px;\n  border: 0;\n  border-radius: var(--dsw-radius-sm, 8px);\n  background: none;\n  color: var(--dsw-alias-label-primary, inherit);\n  font: inherit;\n  text-align: left;\n  cursor: pointer;\n}\n\n.gt-option.gt-option-active {\n  background: var(--dsw-alias-interactive-bg-hover, color-mix(in srgb, currentColor 8%, transparent));\n}\n\n.gt-option.gt-option-selected {\n  background: var(--dsw-alias-button-ghost-active-fill, color-mix(in srgb, currentColor 12%, transparent));\n}\n\n.gt-option-main {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n  min-width: 0;\n  font-size: 12.5px;\n}\n\n.gt-option-name {\n  min-width: 0;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.gt-option-check {\n  display: inline-flex;\n  flex: none;\n  margin-left: auto;\n  color: var(--dsw-alias-state-business-primary, currentColor);\n}\n\n.gt-option-path {\n  overflow: hidden;\n  color: var(--dsw-alias-label-tertiary, inherit);\n  font-family: var(--ds-font-family-code, ui-monospace, SFMono-Regular, Menlo, Consolas, monospace);\n  font-size: 10.5px;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.gt-icon-button {\n  display: inline-flex;\n  flex: 0 0 auto;\n  align-items: center;\n  justify-content: center;\n  width: 26px;\n  height: 26px;\n  padding: 0;\n  border: 0.5px solid var(--dsw-alias-border-l4, currentColor);\n  border-radius: var(--dsw-radius-sm, 8px);\n  background: var(--dsw-alias-bg-layer-1, transparent);\n  color: var(--dsw-alias-label-secondary, inherit);\n  cursor: pointer;\n}\n\n.gt-icon-button:hover:not(:disabled) {\n  background: var(--dsw-alias-interactive-bg-hover, color-mix(in srgb, currentColor 8%, transparent));\n  color: var(--dsw-alias-label-primary, inherit);\n}\n\n.gt-icon-button:focus-visible {\n  outline: var(--dsw-focus-ring-width, 2px) solid var(--dsw-alias-state-business-primary, currentColor);\n  outline-offset: 1px;\n}\n\n.gt-icon-button:disabled {\n  opacity: 0.45;\n  cursor: not-allowed;\n}\n\n.gt-icon-button.gt-icon-button-on {\n  border-color: var(--dsw-alias-state-business-primary, currentColor);\n  background: color-mix(in srgb, var(--dsw-alias-state-business-primary, currentColor) 16%, transparent);\n  color: var(--dsw-alias-state-business-primary, currentColor);\n}\n\n/* \u2500\u2500 status lines \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */\n\n.gt-hint {\n  flex: none;\n  padding: 0 10px 6px;\n  color: var(--dsw-alias-label-tertiary, inherit);\n  font-size: 11.5px;\n  word-break: break-word;\n}\n\n.gt-status {\n  color: var(--dsw-alias-label-secondary, inherit);\n}\n\n.gt-hint-warn {\n  color: var(--dsw-alias-state-warn-primary, inherit);\n}\n\n.gt-hint-launch {\n  margin-top: 3px;\n  color: var(--dsw-alias-state-success-primary, inherit);\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.gt-hint-foot {\n  padding: 10px 12px 16px;\n  color: var(--dsw-alias-label-tertiary, inherit);\n  font-size: 11.5px;\n  text-align: center;\n}\n\n/* \u2500\u2500 filter row \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */\n\n.gt-toolbar {\n  display: flex;\n  flex: none;\n  align-items: center;\n  gap: 8px;\n  padding: 6px 10px;\n  border-top: 0.5px solid var(--dsw-alias-border-l2, currentColor);\n}\n\n.gt-filter-wrap {\n  display: flex;\n  flex: 1 1 auto;\n  align-items: center;\n  gap: 5px;\n  min-width: 0;\n  padding: 3px 8px;\n  border: 0.5px solid var(--dsw-alias-border-l4, currentColor);\n  border-radius: var(--dsw-radius-sm, 8px);\n  background: var(--dsw-alias-bg-layer-1, transparent);\n}\n\n.gt-filter-wrap:focus-within {\n  border-color: var(--dsw-alias-state-business-primary, currentColor);\n}\n\n.gt-filter-icon {\n  display: inline-flex;\n  flex: none;\n  color: var(--dsw-alias-label-tertiary, inherit);\n}\n\n.gt-filter {\n  flex: 1 1 auto;\n  min-width: 0;\n  padding: 0;\n  border: 0;\n  outline: none;\n  background: none;\n  color: inherit;\n  font: inherit;\n  font-size: 12px;\n}\n\n.gt-filter::placeholder {\n  color: var(--dsw-alias-label-tertiary, inherit);\n}\n\n.gt-count {\n  flex: none;\n  color: var(--dsw-alias-label-tertiary, inherit);\n  font-size: 11.5px;\n  font-variant-numeric: tabular-nums;\n}\n\n/* \u2500\u2500 the tree \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */\n\n.gt-scroll {\n  flex: 1 1 auto;\n  min-height: 0;\n  overflow: auto;\n  padding: 2px 6px 12px;\n  scrollbar-color: var(--dsw-alias-scrollbar-bg-l2, transparent) transparent;\n  scrollbar-width: thin;\n}\n\n.gt-row {\n  display: flex;\n  align-items: center;\n  box-sizing: border-box;\n  min-height: 22px;\n  padding-right: 4px;\n  border-radius: var(--dsw-radius-sm, 8px);\n  color: var(--dsw-alias-label-secondary, inherit);\n}\n\n/* One hairline per level, drawn on the row's own left edge: a row indented by\n   padding alone makes a task and its group hard to tell apart, and the rail is\n   what turns the indent into a readable hierarchy. It fades at the row's ends so\n   neighbouring rows join into a continuous line. */\n.gt-guide {\n  flex: none;\n  align-self: stretch;\n  width: 16px;\n  box-sizing: border-box;\n  border-left: 0.5px solid var(--dsw-alias-border-l2, color-mix(in srgb, currentColor 22%, transparent));\n}\n\n.gt-row:hover {\n  background: var(--dsw-alias-interactive-bg-hover, color-mix(in srgb, currentColor 8%, transparent));\n}\n\n.gt-twisty {\n  display: inline-flex;\n  flex: none;\n  align-items: center;\n  justify-content: center;\n  width: 16px;\n  height: 20px;\n  padding: 0;\n  border: 0;\n  background: none;\n  color: var(--dsw-alias-label-tertiary, inherit);\n  cursor: pointer;\n}\n\n.gt-caret {\n  display: inline-block;\n  font-size: 8px;\n  line-height: 1;\n  transition: transform 0.12s ease;\n}\n\n.gt-caret.gt-open {\n  transform: rotate(90deg);\n}\n\n.gt-row-body {\n  display: flex;\n  flex: 1 1 auto;\n  align-items: center;\n  gap: 5px;\n  min-width: 0;\n  padding: 2px 2px;\n  border: 0;\n  background: none;\n  color: inherit;\n  font: inherit;\n  text-align: left;\n  cursor: pointer;\n}\n\n.gt-row-body:focus-visible {\n  outline: var(--dsw-focus-ring-width, 2px) solid var(--dsw-alias-state-business-primary, currentColor);\n  outline-offset: -1px;\n  border-radius: 4px;\n}\n\n.gt-row-icon {\n  display: inline-flex;\n  flex: none;\n  align-items: center;\n  justify-content: center;\n  width: 16px;\n}\n\n.gt-icon-project {\n  color: var(--dsw-alias-state-business-primary, currentColor);\n}\n\n.gt-icon-module {\n  color: var(--dsw-alias-label-secondary, inherit);\n}\n\n.gt-icon-group {\n  color: var(--dsw-alias-label-tertiary, inherit);\n}\n\n.gt-icon-task {\n  color: var(--dsw-alias-label-tertiary, inherit);\n}\n\n.gt-row-name {\n  min-width: 0;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.gt-row-project .gt-row-name {\n  color: var(--dsw-alias-label-primary, inherit);\n  font-weight: 600;\n}\n\n.gt-row-path {\n  flex: 0 1 auto;\n  min-width: 0;\n  overflow: hidden;\n  color: var(--dsw-alias-label-tertiary, inherit);\n  font-size: 10.5px;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.gt-row-module-name {\n  color: var(--dsw-alias-label-primary, inherit);\n}\n\n.gt-row-group .gt-row-name {\n  font-weight: 500;\n}\n\n.gt-row-task-name {\n  font-size: 12.5px;\n}\n\n.gt-badge {\n  display: inline-flex;\n  flex: none;\n  align-items: center;\n  gap: 4px;\n  margin-left: auto;\n  padding-left: 6px;\n  color: var(--dsw-alias-label-tertiary, inherit);\n  font-size: 10.5px;\n  font-variant-numeric: tabular-nums;\n  white-space: nowrap;\n}\n\n.gt-badge-busy {\n  color: var(--dsw-alias-state-business-primary, currentColor);\n}\n\n.gt-row-action {\n  display: inline-flex;\n  flex: 0 0 auto;\n  align-items: center;\n  justify-content: center;\n  width: 18px;\n  height: 18px;\n  margin-left: 2px;\n  padding: 0;\n  border: 0;\n  border-radius: 4px;\n  background: none;\n  color: var(--dsw-alias-label-tertiary, inherit);\n  opacity: 0;\n  cursor: pointer;\n}\n\n.gt-row:hover .gt-row-action,\n.gt-row-action:focus-visible {\n  opacity: 1;\n}\n\n.gt-row-action:hover {\n  color: var(--dsw-alias-label-primary, inherit);\n}\n\n.gt-row-task {\n  color: var(--dsw-alias-label-secondary, inherit);\n}\n\n.gt-row-task:hover .gt-row-task-name {\n  color: var(--dsw-alias-label-primary, inherit);\n}\n\n.gt-row-task.gt-row-selected {\n  background: var(--dsw-alias-interactive-bg-active, color-mix(in srgb, currentColor 14%, transparent));\n  box-shadow: inset 2px 0 0 var(--dsw-alias-state-business-primary, currentColor);\n}\n\n.gt-row-task.gt-row-selected .gt-row-task-name {\n  color: var(--dsw-alias-label-primary, inherit);\n}\n\n.gt-row-task-body:disabled {\n  cursor: progress;\n  opacity: 0.6;\n}\n\n/* The heading between the build-wide list and the subproject rows. It is not a\n   row: nothing folds here, it only names what follows so the same task appearing\n   twice in the tree does not read as a duplicate. */\n.gt-section {\n  display: flex;\n  align-items: center;\n  gap: 4px;\n  margin: 6px 0 2px;\n  padding: 2px 4px 2px 8px;\n  border-top: 0.5px solid var(--dsw-alias-border-l1, color-mix(in srgb, currentColor 14%, transparent));\n  color: var(--dsw-alias-label-tertiary, inherit);\n  font-size: 10.5px;\n  letter-spacing: 0.02em;\n}\n\n.gt-section-text {\n  min-width: 0;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.gt-row-note {\n  padding: 3px 8px 6px 34px;\n  color: var(--dsw-alias-label-tertiary, inherit);\n  font-size: 11.5px;\n  word-break: break-word;\n}\n\n/* A failure is one row like any other: the cause, and a caret when the build\n   log is worth unfolding underneath it. */\n.gt-row-error-box {\n  padding: 0 6px 2px 18px;\n}\n\n.gt-row-error {\n  display: flex;\n  align-items: baseline;\n  gap: 5px;\n  width: 100%;\n  box-sizing: border-box;\n  padding: 2px 4px;\n  border: 0;\n  border-radius: var(--dsw-radius-sm, 8px);\n  background: none;\n  color: var(--dsw-alias-state-error-primary, inherit);\n  font: inherit;\n  font-size: 11.5px;\n  text-align: left;\n  cursor: pointer;\n}\n\n.gt-row-error:disabled {\n  cursor: default;\n}\n\n.gt-row-error:hover:not(:disabled) {\n  background: var(--dsw-alias-interactive-bg-hover-danger, color-mix(in srgb, currentColor 10%, transparent));\n}\n\n.gt-row-error-mark {\n  flex: none;\n  font-weight: 700;\n}\n\n.gt-row-error-text {\n  min-width: 0;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.gt-row-error .gt-caret {\n  flex: none;\n  margin-left: auto;\n  color: var(--dsw-alias-label-tertiary, inherit);\n}\n\n/* The unfolded log keeps the panel's width: it scrolls in both directions\n   rather than pushing the tree sideways. */\n.gt-row-error-log {\n  max-height: 220px;\n  margin: 2px 0 4px;\n  padding: 6px 8px;\n  overflow: auto;\n  border: 0.5px solid var(--dsw-alias-border-l2, currentColor);\n  border-radius: var(--dsw-radius-sm, 8px);\n  background: var(--dsw-alias-bg-layer-1, transparent);\n  color: var(--dsw-alias-label-secondary, inherit);\n  font-family: var(--ds-font-family-code, ui-monospace, SFMono-Regular, Menlo, Consolas, monospace);\n  font-size: 10.5px;\n  line-height: 1.4;\n  white-space: pre;\n  tab-size: 2;\n}\n\n.gt-spinner {\n  animation: gt-spin 0.9s linear infinite;\n  transform-origin: 50% 50%;\n}\n\n@keyframes gt-spin {\n  to { transform: rotate(360deg); }\n}\n\n.gt-empty {\n  padding: 20px 12px;\n  color: var(--dsw-alias-label-tertiary, inherit);\n  font-size: 12px;\n  text-align: center;\n  word-break: break-word;\n}\n\n@media (prefers-reduced-motion: reduce) {\n  .gt-caret,\n  .gt-spinner {\n    transition: none;\n    animation: none;\n  }\n}\n";
